#include <stdio.h>

int main(void) {
    const char *tests[] = {"([]{})", "([)]", "(((", "{[]}", "()(())"};
    for (int t = 0; t < 5; t++) {
        const char *s = tests[t];
        char st[64];
        int top = 0, ok = 1;
        for (int i = 0; s[i]; i++) {
            char c = s[i];
            if (c == '(' || c == '[' || c == '{') { st[top++] = c; }
            else {
                if (top == 0) { ok = 0; break; }
                char o = st[--top];
                if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{')) { ok = 0; break; }
            }
        }
        if (top != 0) ok = 0;
        printf("%-8s -> %s\n", s, ok ? "balanced" : "NOT balanced");
    }
    return 0;
}
